public static IEnumerable<T> Unfold<TState, T>(TState seed, Func<TState, (T item, TState next)?> step)
{
    var state = seed;
    while (step(state) is { } r)      // null means stop
    {
        yield return r.item;          // one layer per MoveNext()
        state = r.next;               // next seed
    }
}
